<?php require __DIR__.'/../config/bootstrap.php'; require_admin(); /* This check was missing: the POST handler below ran before includes/admin_header.php performed the login check, so anyone holding a CSRF token from the public contact form could add or delete records while signed out. */ $admin_title='Projects'; $imgM=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; $vidM=['video/mp4'=>'mp4','video/webm'=>'webm','video/quicktime'=>'mov']; $imageMax=15*1024*1024;$videoMax=50*1024*1024; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$title=post_text('title');$cat=post_text('category');$loc=post_text('location');$year=post_text('year_label');$short=post_text('short_description');$desc=post_text('description');$client=post_text('client_name');$status=in_array($_POST['status']??'', ['Completed','Ongoing','Planning'],true)?$_POST['status']:'Completed';$featured=isset($_POST['featured'])?1:0;if($title===''||$cat===''||$loc===''||$short===''||$desc==='')throw new UserMessageException('Please fill in the title, category, location, short description and full description before saving.');$cover=save_upload($_FILES['cover_image']??['error'=>UPLOAD_ERR_NO_FILE],'uploads/projects',$imgM,$imageMax,true);$video=save_upload($_FILES['project_video']??['error'=>UPLOAD_ERR_NO_FILE],'uploads/projects',$vidM,$videoMax,false);if($id){$st=db()->prepare('SELECT cover_image,project_video FROM projects WHERE id=?');$st->execute([$id]);$old=$st->fetch();$sql='UPDATE projects SET title=?,category=?,location=?,year_label=?,short_description=?,description=?,client_name=?,status=?,featured=?';$params=[$title,$cat,$loc,$year,$short,$desc,$client,$status,$featured];if($cover){$sql.=',cover_image=?';$params[]=$cover;}if($video){$sql.=',project_video=?';$params[]=$video;}$sql.=' WHERE id=?';$params[]=$id;db()->prepare($sql)->execute($params);if($cover&&$old)delete_file($old['cover_image']);if($video&&$old)delete_file($old['project_video']);}else{db()->prepare('INSERT INTO projects(title,category,location,year_label,short_description,description,client_name,status,featured,cover_image,project_video) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$title,$cat,$loc,$year,$short,$desc,$client,$status,$featured,$cover??'',$video??'']);$id=(int)db()->lastInsertId();}$sort=(int)db_value('SELECT COALESCE(MAX(sort_order),0) FROM project_media WHERE project_id=?',[$id]);foreach(save_multiple($_FILES['gallery_images']??[],'uploads/projects',$imgM,$imageMax,true) as $path){$sort++;db()->prepare('INSERT INTO project_media(project_id,media_type,file_path,caption,sort_order) VALUES(?,?,?,?,?)')->execute([$id,'image',$path,trim((string)($_POST['gallery_caption']??'')),$sort]);}foreach(save_multiple($_FILES['gallery_videos']??[],'uploads/projects',$vidM,$videoMax,false) as $path){$sort++;db()->prepare('INSERT INTO project_media(project_id,media_type,file_path,caption,sort_order) VALUES(?,?,?,?,?)')->execute([$id,'video',$path,trim((string)($_POST['gallery_caption']??'')),$sort]);}flash('success','Project and media saved.');header('Location: '.url('admin/projects.php?edit='.$id));exit;}elseif($a==='delete_media'){$mediaId=post_int('media_id');$st=db()->prepare('SELECT file_path,project_id FROM project_media WHERE id=?');$st->execute([$mediaId]);$m=$st->fetch();if(!$m)throw new UserMessageException('That media item has already been removed.');delete_file($m['file_path']);db()->prepare('DELETE FROM project_media WHERE id=?')->execute([$mediaId]);flash('success','Media removed.');header('Location: '.url('admin/projects.php?edit='.(int)$m['project_id']));exit;}elseif($a==='delete'){$id=post_int('id');if($id<1)throw new UserMessageException('That project could not be identified, so nothing was deleted.');$media=db()->prepare('SELECT file_path FROM project_media WHERE project_id=?');$media->execute([$id]);foreach($media->fetchAll() as $m)delete_file($m['file_path']);$st=db()->prepare('SELECT cover_image,project_video FROM projects WHERE id=?');$st->execute([$id]);$p=$st->fetch();if($p){delete_file($p['cover_image']);delete_file($p['project_video']);}db()->prepare('DELETE FROM projects WHERE id=?')->execute([$id]);flash('success','Project deleted.');header('Location: '.url('admin/projects.php'));exit;}}catch(Throwable $e){flash_exception($e);header('Location: '.url('admin/projects.php'.(!empty($_POST['id'])?'?edit='.(int)$_POST['id']:'')));exit;}}$edit=null;$media=[];if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM projects WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();if($edit){$m=db()->prepare('SELECT * FROM project_media WHERE project_id=? ORDER BY sort_order,id');$m->execute([$edit['id']]);$media=$m->fetchAll();}}$items=db()->query('SELECT p.*, (SELECT COUNT(*) FROM project_media pm WHERE pm.project_id=p.id) AS media_count FROM projects p ORDER BY p.created_at DESC, p.id DESC')->fetchAll();require __DIR__.'/../includes/admin_header.php'; ?><div class="admin-card"><div class="admin-card-head"><div><h2><?=$edit?'Edit project':'Add project'?></h2><p>Add one cover image, one featured video and as many gallery images/videos as you need. Admin thumbnails stay compact so large media libraries do not stretch the page.</p></div><?php if($edit):?><a class="small-button" href="<?=e(url('admin/projects.php'))?>">New Project</a><?php endif;?></div><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-cols"><div><label>Project title *</label><input required name="title" value="<?=e($edit['title']??'')?>"></div><div><label>Category *</label><input required name="category" placeholder="Land Survey / Drafting" value="<?=e($edit['category']??'')?>"></div><div><label>Location *</label><input required name="location" value="<?=e($edit['location']??'')?>"></div><div><label>Year</label><input name="year_label" value="<?=e($edit['year_label']??date('Y'))?>"></div><div><label>Client</label><input name="client_name" value="<?=e($edit['client_name']??'')?>"></div><div><label>Status</label><select name="status"><?php foreach(['Completed','Ongoing','Planning'] as $x):?><option <?=$x===($edit['status']??'Completed')?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="wide"><label>Short description *</label><input required name="short_description" value="<?=e($edit['short_description']??'')?>"></div><div class="wide"><label>Full description *</label><textarea required name="description" rows="7"><?=e($edit['description']??'')?></textarea></div><div><label>Cover image</label><input type="file" name="cover_image" accept=".jpg,.jpeg,.png,.webp"><small>JPG, PNG or WebP • maximum 15 MB • automatically optimized when GD is available.</small></div><div><label>Featured project video</label><input type="file" name="project_video" accept=".mp4,.webm,.mov"><small>MP4 recommended • maximum 50 MB.</small></div><div class="wide"><label>Gallery images</label><input type="file" name="gallery_images[]" multiple accept=".jpg,.jpeg,.png,.webp"><small>Select many images. Each is optimized and shown as a compact admin thumbnail.</small></div><div class="wide"><label>Gallery videos</label><input type="file" name="gallery_videos[]" multiple accept=".mp4,.webm,.mov"><small>Videos are stored as separate project media and displayed on the public project page.</small></div><div class="wide"><label>Media caption</label><input name="gallery_caption" maxlength="255" placeholder="Example: Topographical survey field work"></div></div><label class="check"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Feature this project on the homepage</label><button class="admin-button" type="submit"><?= $edit?'Save Project & Media':'Create Project'?></button></form></div><?php if($edit&&$media):?><div class="admin-card"><div class="admin-card-head"><div><h2>Project media</h2><p><?=count($media)?> media item(s)</p></div></div><div class="admin-media-grid"><?php foreach($media as $m):?><div class="admin-media-item"><?php if($m['media_type']==='image'):?><img src="<?=e(asset_url($m['file_path']))?>" alt=""><?php else:?><video controls preload="metadata"><source src="<?=e(asset_url($m['file_path']))?>" type="<?=e(media_type_for($m['file_path']))?>"></video><?php endif;?><div><small><?=e(strtoupper($m['media_type']))?></small><form method="post" data-confirm="Remove this media item?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_media"><input type="hidden" name="media_id" value="<?=(int)$m['id']?>"><input type="hidden" name="project_id" value="<?=(int)$edit['id']?>"><button>Remove</button></form></div></div><?php endforeach;?></div></div><?php endif;?><div class="admin-card"><div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Category</th><th>Media</th><th>Status</th><th>Featured</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><strong><?=e($p['title'])?></strong><small><?=e($p['location'])?></small></td><td><?=e($p['category'])?></td><td><?=e($p['media_count'])?> item(s)</td><td><?=e($p['status'])?></td><td><?=!empty($p['featured'])?'Yes':'No'?></td><td class="actions"><a href="?edit=<?=(int)$p['id']?>">Manage</a><form method="post" data-confirm="Delete this project and all media?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/admin_footer.php'; ?>